ALLOWED_ROOTS = {"backend", "frontend", "ops", "deploy"}

def main() -> None:
    root = Path.cwd().resolve()
    data = base64.b64decode(PAYLOAD)
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED_SHA256:
        raise SystemExit("Bundle corrompido: checksum SHA-256 invalido.")

    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tf:
        members = []
        for member in tf.getmembers():
            p = Path(member.name)
            if not p.parts or p.parts[0] not in ALLOWED_ROOTS:
                raise SystemExit(f"Caminho inesperado no bundle: {member.name}")
            target = (root / p).resolve()
            if root not in target.parents and target != root:
                raise SystemExit(f"Caminho inseguro no bundle: {member.name}")
            members.append(member)
        tf.extractall(root, members=members, filter="data")

    print("MailFlow: backend/, frontend/, ops/ e deploy/ reconstruidos com sucesso.")

if __name__ == "__main__":
    main()
